begin;
create temporary table duty_feature_tests(test text,passed boolean) on commit drop;
do $$
declare b integer;f uuid;f2 uuid;k uuid;s uuid;m uuid;d uuid;d2 uuid;staff bigint;oid bigint;handover uuid;j jsonb;lim integer;c2 bigint;b2 integer;
begin
 select branch_id,user_id into b,f from public.dlv_profiles where active and workflow_role='callcenter_followup' limit 1;
 select user_id into f2 from public.dlv_profiles where active and branch_id=b and workflow_role='callcenter_followup' and user_id<>f limit 1;
 select user_id into k from public.dlv_profiles where active and branch_id=b and workflow_role='kitchen' limit 1;
 select user_id into s from public.dlv_profiles where active and branch_id=b and workflow_role='supervisor' limit 1;
 select user_id into m from public.dlv_profiles where active and branch_id=b and workflow_role='manager' limit 1;
 select p.user_id into d from public.dlv_profiles p where p.active and p.branch_id=b and p.role='driver' and not exists(select 1 from public.dlv_orders o where o.driver_id=p.user_id and o.status in ('new','received','out')) limit 1;
 select p.user_id into d2 from public.dlv_profiles p where p.active and p.branch_id=b and p.role='driver' and p.user_id<>d and not exists(select 1 from public.dlv_orders o where o.driver_id=p.user_id and o.status in ('new','received','out')) limit 1;
 select id into staff from public.dlv_callcenter_staff where active and branch_id=b limit 1;
 if f2 is null or d2 is null then raise exception 'Missing test participants';end if;
 perform set_config('request.jwt.claim.sub',d::text,true);perform public.dlv_set_my_driver_duty('available');
 perform set_config('request.jwt.claim.sub',d2::text,true);perform public.dlv_set_my_driver_duty('break');
 perform set_config('request.jwt.claim.sub',f::text,true);oid:=public.dlv_create_order('QA-DUTY-'||substr(gen_random_uuid()::text,1,10),null,null,null,null,null,b,staff);
 select coalesce(kitchen_minutes,25) into lim from public.dlv_branch_sla where branch_id=b;lim:=coalesce(lim,25);
 update public.dlv_orders set kitchen_received_at=now()-make_interval(mins=>lim+5) where id=oid;
 perform private.dlv_scan_stage_delays(b);perform public.dlv_record_delay_reason(oid,'kitchen_load','QA followup action');
 if not exists(select 1 from private.dlv_stage_followups where order_id=oid and reason_code='kitchen_load' and action_by=f) then raise exception 'Reason not saved';end if;
 begin perform public.dlv_record_delay_reason(oid,'invalid','QA reason');raise exception 'Invalid reason accepted';exception when raise_exception then if sqlerrm<>'سبب غير صحيح' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',m::text,true);j:=public.dlv_delay_reason_summary((now() at time zone 'Africa/Cairo')::date,b);if not exists(select 1 from jsonb_array_elements(j) x where x->>'reason'='kitchen_load') then raise exception 'Missing reason summary';end if;
 insert into duty_feature_tests values('structured_reasons_attribution_and_summary',true);
 perform set_config('request.jwt.claim.sub',k::text,true);perform public.dlv_kitchen_forward(oid,null);
 perform set_config('request.jwt.claim.sub',s::text,true);perform public.dlv_supervisor_receive(oid,null);j:=public.dlv_suggest_drivers(oid);
 if exists(select 1 from jsonb_array_elements(j) x where x->>'user_id'=d2::text) then raise exception 'Break driver suggested';end if;
 if not exists(select 1 from jsonb_array_elements(j) x where x->>'user_id'=d::text) then raise exception 'Available driver missing';end if;
 perform public.dlv_assign_driver(oid,d,null);
 perform set_config('request.jwt.claim.sub',d::text,true);j:=public.dlv_my_driver_duty();if j->>'state'<>'delivering' then raise exception 'Not derived from active orders';end if;
 begin perform public.dlv_set_my_driver_duty('off_shift');raise exception 'Ended with open orders';exception when raise_exception then if sqlerrm='Ended with open orders' then raise;end if;end;
 insert into duty_feature_tests values('driver_availability_suggestions_and_open_order_guard',true);
 perform set_config('request.jwt.claim.sub',f::text,true);handover:=public.dlv_create_shift_handover(b,'QA synthetic handover');
 begin perform public.dlv_accept_shift_handover(handover);raise exception 'Self acceptance allowed';exception when raise_exception then if sqlerrm<>'لا يمكنك استلام تسليم أنشأته بنفسك' then raise;end if;end;
 begin perform public.dlv_create_shift_handover(b,'QA duplicate');raise exception 'Duplicate handover';exception when raise_exception then if sqlerrm<>'يوجد تسليم سابق بانتظار الاستلام' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',k::text,true);j:=public.dlv_list_shift_handovers(b);if exists(select 1 from jsonb_array_elements(j) x where x->>'id'=handover::text) then raise exception 'Kitchen saw followup handover';end if;
 perform set_config('request.jwt.claim.sub',f2::text,true);perform public.dlv_accept_shift_handover(handover);
 if not exists(select 1 from private.dlv_shift_handovers where id=handover and accepted_by=f2 and accepted_at is not null) then raise exception 'No acceptance attribution';end if;
 insert into duty_feature_tests values('handover_snapshot_role_scope_and_independent_acceptance',true);
 insert into public.dlv_companies(name,slug,active,onboarding_status) values('QA duty company','qa-duty-'||substr(gen_random_uuid()::text,1,8),true,'active') returning id into c2;
 select coalesce(min(id),0)-1 into b2 from public.dlv_branches;insert into public.dlv_branches(id,name,company_id) values(b2,'QA duty branch '||gen_random_uuid()::text,c2);
 update public.dlv_profiles set branch_id=b2,allowed_branch_ids=array[b2] where user_id=f2;
 begin perform public.dlv_list_shift_handovers(b);raise exception 'Cross company handover';exception when raise_exception then if sqlerrm<>'غير مصرح' then raise;end if;end;
 begin perform public.dlv_create_shift_handover(b,'QA forbidden');raise exception 'Cross company create';exception when raise_exception then if sqlerrm<>'غير مصرح' then raise;end if;end;
 begin perform public.dlv_set_my_driver_duty('available');raise exception 'Non driver changed duty';exception when raise_exception then if sqlerrm<>'غير مصرح' then raise;end if;end;
 insert into duty_feature_tests values('second_company_and_non_driver_access_denied',true);
end $$;
select * from duty_feature_tests;
rollback;
